<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='delete'&&$id){db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]);$success='Product deleted.';}elseif(in_array($action,['create','update'],true)){
 $name=trim((string)($_POST['name']??''));$sku=strtoupper(trim((string)($_POST['sku']??'')));$description=trim((string)($_POST['description']??''));$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$sale=trim((string)($_POST['sale_price']??''));$sale=$sale===''?null:filter_var($sale,FILTER_VALIDATE_FLOAT);$stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT);$category=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT)?:null;$unit=trim((string)($_POST['unit']??'metre'));$colour=trim((string)($_POST['colour']??''));$material=trim((string)($_POST['material']??''));$featured=isset($_POST['is_featured'])?1:0;
 if($name===''||$sku===''||$description===''||$price===false||$price<0||$stock===false||$stock<0||($sale!==null&&($sale===false||$sale<0||$sale>$price))){$error='Check the product name, SKU, description, price and stock.';}else{try{$image=save_uploaded_image('image','products');$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$name)),'-'));if($action==='create'){$stmt=db()->prepare('INSERT INTO products (category_id,name,slug,sku,description,price,sale_price,stock,unit,colour,material,image,is_featured) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$category,$name,$slug.'-'.strtolower(bin2hex(random_bytes(3))),$sku,$description,$price,$sale,$stock,$unit,$colour?:null,$material?:null,$image,$featured]);$success='Product created.';}elseif($id){if($image){$stmt=db()->prepare('UPDATE products SET category_id=?,name=?,sku=?,description=?,price=?,sale_price=?,stock=?,unit=?,colour=?,material=?,image=?,is_featured=? WHERE id=?');$stmt->execute([$category,$name,$sku,$description,$price,$sale,$stock,$unit,$colour?:null,$material?:null,$image,$featured,$id]);}else{$stmt=db()->prepare('UPDATE products SET category_id=?,name=?,sku=?,description=?,price=?,sale_price=?,stock=?,unit=?,colour=?,material=?,is_featured=? WHERE id=?');$stmt->execute([$category,$name,$sku,$description,$price,$sale,$stock,$unit,$colour?:null,$material?:null,$featured,$id]);}$success='Product updated.';}}catch(RuntimeException|PDOException $exception){$error=$exception instanceof RuntimeException?$exception->getMessage():($exception->getCode()==='23000'?'That SKU is already in use.':'Product could not be saved.');error_log('Product save failed: '.$exception->getMessage());}}
}}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT);$edit=null;if($editId){$stmt=db()->prepare('SELECT * FROM products WHERE id=?');$stmt->execute([$editId]);$edit=$stmt->fetch()?:null;}
$categories=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$products=db()->query('SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();
$adminTitle='Products · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Products</h1><p class="mt-2 text-sm text-gray-600">Manage the live fabric collection and stock.</p><?php foreach([$error,$success] as $notice):if($notice):?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($notice) ?></p><?php endif;endforeach;?>
<section class="mt-7 bg-white p-5"><h2 class="font-serif text-2xl"><?= $edit?'Edit product':'Add a product' ?></h2><form method="post" enctype="multipart/form-data" class="mt-5 grid gap-4 sm:grid-cols-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label class="text-sm">Product name<input class="form-control mt-1" name="name" required value="<?= e($edit['name']??'') ?>"></label><label class="text-sm">SKU<input class="form-control mt-1" name="sku" required value="<?= e($edit['sku']??'') ?>"></label><label class="text-sm">Category<select class="form-control mt-1" name="category_id"><option value="">Uncategorised</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm">Unit<input class="form-control mt-1" name="unit" value="<?= e($edit['unit']??'metre') ?>" required></label><label class="text-sm">Price<input class="form-control mt-1" name="price" type="number" step=".01" min="0" required value="<?= e($edit['price']??'') ?>"></label><label class="text-sm">Sale price (optional)<input class="form-control mt-1" name="sale_price" type="number" step=".01" min="0" value="<?= e($edit['sale_price']??'') ?>"></label><label class="text-sm">Stock<input class="form-control mt-1" name="stock" type="number" min="0" step="1" required value="<?= e($edit['stock']??0) ?>"></label><label class="text-sm">Colour<input class="form-control mt-1" name="colour" value="<?= e($edit['colour']??'') ?>"></label><label class="text-sm">Material<input class="form-control mt-1" name="material" value="<?= e($edit['material']??'') ?>"></label><label class="text-sm">Product image (JPG, PNG, WebP · max 5 MB)<input class="form-control mt-1" name="image" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="text-sm sm:col-span-2">Description<textarea class="form-control mt-1" name="description" rows="3" required><?= e($edit['description']??'') ?></textarea></label><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_featured" <?= !empty($edit['is_featured'])?'checked':'' ?>> Feature on homepage</label><div class="flex gap-4 sm:col-span-2"><button class="rounded-full bg-forest px-6 py-3 text-sm font-semibold text-white"><?= $edit?'Save changes':'Add product' ?></button><?php if($edit): ?><a class="self-center text-sm underline" href="<?= e(url('admin/products/index.php')) ?>">Cancel</a><?php endif; ?></div></form></section>
<section class="mt-7 overflow-x-auto bg-white p-5"><h2 class="font-serif text-2xl">All products</h2><table class="mt-5 w-full min-w-[760px] text-left text-sm"><thead class="text-xs uppercase text-gray-500"><tr><th class="py-3">Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $product): ?><tr class="border-t border-black/5"><td class="py-3"><strong><?= e($product['name']) ?></strong><br><span class="text-xs text-gray-500"><?= e($product['sku']) ?></span></td><td><?= e($product['category_name']??'—') ?></td><td><?= e(money($product['sale_price']??$product['price'])) ?></td><td><?= (int)$product['stock'] ?></td><td><?= $product['is_active']?'Active':'Hidden' ?></td><td class="flex gap-3 py-3"><a class="underline" href="?edit=<?= (int)$product['id'] ?>">Edit</a><form method="post" data-confirm="Delete this product?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><button class="text-red-700 underline">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></section>
